// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.impl.restrictions;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.stream.IntStream;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class RestrictionFrameTest {
	private final QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
	private final SimpleValueFactory vf = SimpleValueFactory.getInstance();

	@Test
	void conflictingAliasesRetainUnboundOriginalRows() {
		RestrictionLayout exports = new RestrictionLayout(List.of("a", "b", "hidden"), context);
		RestrictionLayout child = new RestrictionLayout(List.of("x", "hidden"), context);
		Value first = vf.createLiteral("01", XSD.INTEGER);
		Value second = vf.createLiteral("1", XSD.INTEGER);
		var row = new MapBindingSet();
		row.addBinding("a", first);
		row.addBinding("b", second);
		row.addBinding("hidden", first);
		RestrictionFrame transferred = exports.capture(row, null).transfer(child, new int[] { 0, 0, -1 });
		assertThat(transferred.unboundOnly(0)).isTrue();
		var original = new MapBindingSet();
		original.addBinding("hidden", second);
		assertThat(transferred.accepts(original)).isTrue();
		original.addBinding("x", first);
		assertThat(transferred.accepts(original)).isFalse();
		original.setBinding("x", second);
		assertThat(transferred.accepts(original)).isFalse();
	}

	@Test
	void snapshotsActualMasksAcrossWordBoundaries() {
		RestrictionLayout layout = new RestrictionLayout(IntStream.range(0, 130).mapToObj(i -> "v" + i).toList(),
				context);
		Value one = vf.createLiteral(1);
		Value two = vf.createLiteral(2);
		var row = new MapBindingSet();
		for (int i : new int[] { 0, 63, 64, 129 }) {
			row.addBinding(layout.name(i), one);
		}
		RestrictionFrame frame = layout.capture(row,
				value -> vf.createLiteral(value.stringValue(), ((Literal) value).getDatatype()));
		row.setBinding("v129", two);
		assertThat(frame.value(129)).isEqualTo(one);
		assertThat(frame.value(65)).isNull();
		assertThat(frame.unboundOnly(65)).isFalse();
		assertThat(frame.accepts(row)).isFalse();
		assertThat(frame.accepts(new MapBindingSet())).isTrue();
		assertThat(frame.restrict(129, two).unboundOnly(129)).isTrue();
		assertThat(layout.capture(new MapBindingSet(), null)).isSameAs(layout.unrestricted());
	}
}
